window.WORDS = window.WORDS || [];
WORDS.push(["Mark", 1, 15, 15, "Thời kỳ đã mãn, Nước Thiên Chúa đã đến gần", "The time is fulfilled; the Kingdom of God is at hand", "Đây là lời đầu tiên Chúa Giêsu nói trong Tin Mừng Máccô, như bản tóm tắt cả sứ vụ Người. “Thời kỳ đã mãn”: Thiên Chúa thực hiện lời hứa; Nước Thiên Chúa không còn xa mà đã đến gần vì chính Người hiện diện. Đáp lại có hai việc: sám hối (đổi hướng cuộc sống) và tin vào Tin Mừng.", "These are the first words of Jesus in Mark, a summary of his whole ministry. “The time is fulfilled”: God fulfils his promise; the Kingdom is no longer far but near because he himself is present. Two responses are asked: repent (change direction) and believe in the Gospel.", "Mỗi ngày là “thời kỳ mãn” để quay về với Chúa. Đừng chờ dịp thuận tiện; hãy bắt đầu hoán cải bằng một việc cụ thể hôm nay.", "Every day is a “fullness of time” to return to God. Do not wait for a convenient moment; begin conversion with one concrete act today."]);
WORDS.push(["Mark", 1, 17, 17, "Hãy theo Thầy, Thầy sẽ làm cho anh em thành người lưới người", "Follow me; I will make you fishers of men", "Chúa gọi Simon và Anrê đang quăng lưới. Lời gọi ngắn và có sức mạnh: họ bỏ lưới đi theo ngay. Chúa không chỉ gọi mà còn hứa sẽ làm cho họ nên, nghĩa là ơn gọi là công trình của Chúa nơi người đáp lại.", "The Lord calls Simon and Andrew casting nets. The call is brief and powerful: they leave their nets and follow at once. He not only calls but promises to make them into something, so vocation is God’s work in those who respond.", "Đừng nghĩ “tôi không đủ khả năng”. Chúa gọi rồi sẽ làm cho nên. Việc của ta là bước theo.", "Do not think “I am not capable.” The Lord calls then forms. Our part is to follow."]);
WORDS.push(["Mark", 1, 38, 38, "Chúng ta hãy đi nơi khác để Thầy cũng rao giảng", "Let us go elsewhere that I may preach there also", "Sau khi cầu nguyện lúc sáng sớm, Chúa nói với các môn đệ đang tìm Người rằng phải đi nơi khác: Người đến để rao giảng chứ không chỉ để chữa bệnh và được nổi tiếng. Cầu nguyện giúp Người giữ đúng sứ mạng giữa lúc thành công.", "After early-morning prayer the Lord tells disciples seeking him that they must go elsewhere: he came to preach, not merely to heal and be popular. Prayer helps him keep his mission when success tempts.", "Khi thành công và lời khen kéo ta khỏi mục đích, hãy cầu nguyện để tìm lại điều Chúa thực sự mời gọi.", "When success and praise pull you from your purpose, pray to rediscover what the Lord really calls you to."]);
WORDS.push(["Mark", 1, 41, 44, "Ta muốn, hãy nên sạch", "I will; be clean", "Chúa chạm vào người phong hủi vì thương xót. Hai chữ “Ta muốn” cho thấy lòng Thiên Chúa không thờ ơ trước đau khổ. Người dặn anh đừng nói ai mà đến trình thầy tư tế. Đó là cách tôn trọng Luật và để người ấy được nhận lại vào cộng đoàn.", "The Lord touches the leper out of compassion. The words “I will” show God’s heart is not indifferent to suffering. He tells him to tell no one but to show himself to the priest. This respects the Law and lets the man be restored to community.", "Hãy chạm đến đau khổ của anh chị em quanh mình thay vì đứng xa. Lòng thương xót là hành động.", "Touch the suffering of those around you instead of standing apart. Compassion is action."]);
WORDS.push(["Mark", 2, 5, 11, "Tha tội và chữa lành người bại", "Forgiveness and healing of the paralytic", "Chúa thấy đức tin của những người khiêng, rồi nói trước hết: “Con ơi, tội con được tha.” Các kinh sư nghĩ: chỉ Thiên Chúa mới tha tội. Chúa biết họ nghĩ và nói: “Thế nào dễ hơn…?” Người chữa cả thân xác để chứng tỏ có quyền tha tội. Đức tin của bạn bè cũng có thể đem người khác đến với Chúa.", "The Lord sees the faith of those carrying him and says first: “Son, your sins are forgiven.” The scribes think: only God forgives sins. He knows their thoughts and asks: “Which is easier…?” He heals the body too to prove he has authority to forgive. The faith of friends can bring others to the Lord.", "Hãy là “người khiêng” cho anh em: cầu nguyện, đưa họ đến với Chúa. Và đừng sợ để người khác giúp mình đến với Chúa.", "Be a “stretcher-bearer” for others: pray and bring them to the Lord. And do not be afraid to let others help you come to him."]);
WORDS.push(["Mark", 2, 17, 17, "Không phải người khỏe mà là người bệnh cần thầy thuốc", "Not the healthy but the sick need a doctor", "Chúa trả lời những người chê Người ăn với người thu thuế và tội nhân. Người ví mình như thầy thuốc đến với người đau. Không phải Người coi nhẹ tội mà để chữa tội bằng lòng thương xót. Ai tự cho mình khỏe thì không nhận ra mình cần Người.", "The Lord answers those criticizing him for eating with tax collectors and sinners. He likens himself to a physician coming to the sick. He does not treat sin lightly but heals it by mercy. Those who think themselves healthy do not see their need of him.", "Đừng xấu hổ nhận mình là tội nhân đến với Chúa; đó là điều kiện để được chữa lành.", "Do not be ashamed to come to the Lord as a sinner; that is the condition for healing."]);
WORDS.push(["Mark", 2, 19, 22, "Chàng rể ở cùng, vải mới rượu mới", "The bridegroom is here; new cloth and new wine", "Khi bị hỏi vì sao môn đệ không ăn chay, Chúa nói khách dự tiệc cưới không ăn chay khi chàng rể còn ở với họ. Thời của Người là thời vui mừng. Nhưng sẽ có ngày Người bị cất đi và họ mới ăn chay. Vải mới, rượu mới nói đến điều mới Người mang đến cần tâm hồn mới.", "Asked why the disciples do not fast, the Lord says wedding guests do not fast while the bridegroom is with them. His time is one of joy. But a day will come when he is taken away and they will fast. New cloth and new wine point to the newness he brings requiring a new heart.", "Chúa hiện diện là niềm vui của người tin. Hãy sống đạo với niềm vui chứ không chỉ với bổn phận nặng nề.", "The Lord’s presence is the believer’s joy. Live faith with joy, not only burdensome duty."]);
WORDS.push(["Mark", 2, 25, 28, "Ngày sabát dành cho con người", "The Sabbath was made for man", "Chúa nhắc việc vua Đavít và các tùy tùng ăn bánh tiến khi đói. Rồi Người nói: ngày sabát được làm ra vì con người, không phải con người vì ngày sabát; và Con Người làm chủ cả ngày sabát. Điều răn nhằm giúp con người sống trọn vẹn, không phải gánh nặng; và Người có quyền trên Luật.", "The Lord recalls David and his companions eating the bread of offering when hungry. Then: the Sabbath was made for man, not man for the Sabbath; and the Son of Man is Lord even of the Sabbath. Commandments help humans live fully, not as burdens; and he has authority over the Law.", "Giữ ngày Chúa nhật là món quà để nghỉ ngơi và gặp Chúa, không chỉ là nghĩa vụ. Hãy giữ với niềm vui.", "Keeping Sunday is a gift of rest and meeting the Lord, not just duty. Keep it with joy."]);
WORDS.push(["Mark", 3, 4, 5, "Ngày sabát được phép làm điều lành hay điều dữ?", "Is it lawful to do good or harm on the Sabbath?", "Trước người có bàn tay teo, Chúa hỏi: được làm điều lành hay điều dữ, cứu mạng hay giết? Họ làm thinh. Người nhìn quanh với giận dữ và đau buồn vì họ cứng lòng. Chúa giận vì sự thờ ơ trước người đau khổ, và đau buồn vì họ không hiểu. Không làm điều lành khi có thể cũng là một lựa chọn xấu.", "Before a man with a withered hand the Lord asks: is it lawful to do good or harm, to save life or kill? They are silent. He looks around with anger and grief at their hardness of heart. He is angry at indifference to suffering and grieved at their lack of understanding. Not doing good when we can is also a bad choice.", "Đừng chỉ tránh làm điều xấu. Tội thiếu sót, không giúp khi có thể, cũng là điều phải xét mình.", "Do not merely avoid evil. Sins of omission, not helping when we can, also need examining."]);
WORDS.push(["Mark", 3, 23, 29, "Nội bộ chia rẽ và tội phạm đến Thánh Thần", "A house divided and sin against the Spirit", "Họ nói Chúa trừ quỷ nhờ chúa quỷ. Chúa chứng minh bằng lý lẽ: Satan không thể tự chống Satan. Người so sánh việc trói kẻ mạnh trước khi cướp nhà. Rồi Người cảnh cáo: mọi tội được tha, trừ tội phạm đến Thánh Thần, vì gán việc của Chúa cho quỷ là cố tình chối ơn cứu độ. Gốc của tội này là từ chối nhận ra việc Thiên Chúa làm.", "They say he casts out demons by the prince of demons. He shows by logic that Satan cannot oppose himself. He compares binding the strong man before plundering his house. Then he warns: all sins can be forgiven except blasphemy against the Spirit, for attributing God’s work to the devil is deliberately refusing salvation. Its root is refusing to recognize what God does.", "Hãy học nhận ra việc Chúa làm nơi người khác và trong đời mình, và biết tạ ơn thay vì nghi ngờ.", "Learn to recognize God’s work in others and in your life, and give thanks rather than suspect."]);
WORDS.push(["Mark", 3, 33, 35, "Gia đình mới của Chúa Giêsu", "The new family of Jesus", "Khi mẹ và anh em của Chúa đứng ngoài tìm Người, Chúa nhìn những người ngồi quanh và nói: đây là mẹ tôi và anh em tôi, ai thi hành ý Thiên Chúa. Lời này mở rộng gia đình Chúa ra cho mọi người nghe và sống Lời Chúa; và đưa Mẹ Maria lên hàng đầu vì Mẹ là người nghe và làm theo.", "When his mother and brothers stand outside seeking him, the Lord looks at those seated around and says: here are my mother and my brothers; whoever does the will of God. This widens his family to all who hear and live God’s word, and puts Mary first since she hears and does.", "Hội Thánh là gia đình thật của ta. Hãy dành thời gian và tình cảm cho anh chị em trong đức tin.", "The Church is our true family. Give time and affection to brothers and sisters in faith."]);
WORDS.push(["Mark", 4, 3, 9, "Dụ ngôn người gieo giống", "The parable of the sower", "Hạt giống rơi bốn loại đất; chỉ đất tốt sinh hoa trái, ba mươi, sáu mươi, một trăm. Chúa mở đầu bằng “Hãy nghe” và kết bằng “Ai có tai nghe thì nghe”, nhấn mạnh việc lắng nghe là điều cốt yếu. Lời Chúa được gieo rộng rãi; kết quả tùy chỗ ta đón nhận.", "The seed falls on four soils; only good soil bears fruit, thirty, sixty, a hundredfold. The Lord begins with “Listen” and ends “He who has ears let him hear,” stressing listening as essential. The word is sown generously; the result depends on our reception.", "Hãy dành một lúc yên tĩnh mỗi ngày để nghe Lời Chúa; đó là cách làm tơi đất lòng.", "Set aside a quiet moment each day to hear God’s word; that tills the soil of the heart."]);
WORDS.push(["Mark", 4, 11, 20, "Mầu nhiệm Nước Trời và lời giải thích", "The mystery of the Kingdom and the explanation", "Chúa nói mầu nhiệm Nước Trời được trao cho các môn đệ, còn người ngoài chỉ thấy dụ ngôn. Rồi Người giải thích: hạt giống là Lời; ven đường là người nghe mà Satan cướp mất; đá sỏi là người vui vẻ nhưng không rễ; gai góc là lo toan, giàu sang, ham muốn; đất tốt là người nghe, đón nhận và sinh hoa trái. Mỗi hoàn cảnh thật có một cách để Lời bị cản trở.", "The Lord says the mystery of the Kingdom is given to the disciples while outsiders get parables. He explains: the seed is the Word; the path is hearers from whom Satan snatches it; rocky ground is those with joy but no root; thorns are worries, riches and desires; good soil is those who hear, accept and bear fruit. Each real situation has its way of blocking the Word.", "Hãy xét xem điều gì đang cản Lời Chúa trong đời mình: bận rộn, giàu sang, ham muốn? Và quyết định gỡ bớt một “gai”.", "Examine what blocks God’s word in your life: busyness, wealth, desires? Decide to remove one “thorn.”"]);
WORDS.push(["Mark", 4, 21, 25, "Ngọn đèn và thước đo", "The lamp and the measure", "Không ai thắp đèn rồi giấu dưới thùng; điều kín cũng sẽ lộ ra. Lời Chúa là ánh sáng phải được chiếu soi. Người nhắc: hãy cẩn thận điều anh em nghe; anh em đong bằng đấu nào thì sẽ được đong lại bằng đấu ấy. Ai có thì được thêm: ơn nhận được và thực hành sẽ sinh thêm ơn.", "No one lights a lamp to hide it; what is hidden will be revealed. God’s word is light to shine. He adds: take care what you hear; the measure you give will be given back. To the one who has more will be given: grace received and practised generates more grace.", "Hãy chia sẻ điều Chúa dạy cho người khác. Càng cho đi, ta càng nhận thêm.", "Share what the Lord teaches with others. The more we give, the more we receive."]);
WORDS.push(["Mark", 4, 26, 32, "Hạt giống tự mọc và hạt cải", "The seed growing by itself and the mustard seed", "Máccô chỉ có dụ ngôn hạt giống tự lớn: người gieo ngủ thức, hạt tự mọc mà người không biết cách; đến mùa thì gặt. Nước Chúa lớn lên nhờ sức mạnh của Chúa, không do kỹ thuật ta. Hạt cải bé nhỏ sẽ thành cây lớn cho chim trú ngụ: bắt đầu khiêm tốn mà kết quả vượt xa.", "Only Mark has the parable of the seed growing by itself: the sower sleeps and rises, the seed sprouts he knows not how; at harvest he reaps. God’s Kingdom grows by God’s power, not by our technique. The tiny mustard seed becomes a great shrub sheltering birds: humble beginning, far greater outcome.", "Hãy gieo hạt (lời nói, việc tốt) rồi kiên nhẫn để Chúa làm cho lớn lên. Đừng nản vì chưa thấy kết quả.", "Sow seeds (words, good works) and patiently let God make them grow. Do not discourage because you do not yet see results."]);
WORDS.push(["Mark", 4, 35, 40, "Sao các con nhát đảm, chưa có đức tin sao?", "Why are you afraid? Have you no faith?", "Giữa cơn bão Chúa ngủ trên gối. Các môn đệ đánh thức Người: “Thầy chẳng lo gì chúng ta chết sao?” Chúa truyền cho sóng gió im lặng rồi hỏi về đức tin. Đức tin là tin rằng Chúa ở trong thuyền với ta dù Người có vẻ im lặng. Rồi họ sợ hãi hơn trước quyền năng của Người: “Ông này là ai?”", "In the storm the Lord sleeps on a cushion. The disciples wake him: “Teacher, do you not care that we perish?” He commands the wind and sea to be still, then asks about faith. Faith is trust that the Lord is in the boat with us though seemingly silent. Then they fear him more: “Who then is this?”", "Khi bão tố cuộc đời đến, hãy cầu nguyện thẳng thắn với Chúa và tin rằng Người ở trong thuyền.", "When life’s storms come, pray frankly to the Lord and trust he is in the boat."]);
WORDS.push(["Mark", 5, 19, 19, "Hãy về nói với người nhà điều Chúa đã làm cho anh", "Go home and tell what the Lord has done", "Người được giải thoát khỏi đạo binh quỷ xin theo Chúa. Chúa từ chối và nói: hãy về nhà, kể cho người thân điều Chúa đã làm cho anh và lòng thương xót của Người. Sứ mạng đầu tiên của người được chữa lành là làm chứng ngay nơi mình sống.", "The man freed from Legion begs to follow Jesus. The Lord refuses and says: go home to your people and tell them how much the Lord has done for you and the mercy he has shown. The healed person’s first mission is to bear witness right where he lives.", "Hãy kể cho người nhà và bạn bè điều Chúa đã làm trong đời mình. Lời chứng chân thật rất có sức thuyết phục.", "Tell family and friends what the Lord has done in your life. Honest testimony is persuasive."]);
WORDS.push(["Mark", 5, 34, 36, "Đức tin con đã cứu con; đừng sợ, chỉ cần tin", "Your faith has saved you; do not fear, only believe", "Chúa gọi người phụ nữ là “con” sau khi bà can đảm thú nhận. Người bảo bà bình an và khỏi bệnh. Khi người ta báo con ông Giairô đã chết, Chúa nói với cha em: “Đừng sợ, chỉ cần tin.” Sợ hãi và tin tưởng đối nghịch nhau; Chúa mời ta chọn tin ngay cả khi hoàn cảnh có vẻ vô vọng.", "The Lord calls the woman “daughter” after she courageously confesses. He tells her to go in peace and be healed. When told Jairus’s daughter is dead, he says: “Do not fear, only believe.” Fear and trust oppose each other; the Lord invites us to choose belief even when hope seems gone.", "Khi tin xấu đến, hãy lặp lại lời Chúa: “Đừng sợ, chỉ cần tin.” Và phó thác tình huống cho Người.", "When bad news comes repeat the Lord’s words: “Do not fear, only believe.” And entrust the situation to him."]);
WORDS.push(["Mark", 5, 39, 41, "Talitha kum: Em bé, dậy đi", "Talitha kum: little girl, arise", "Chúa nói em chỉ ngủ rồi cầm tay em và nói bằng tiếng Aram: “Talitha kum”. Tin Mừng giữ nguyên tiếng gốc của lời Chúa, như muốn nói lời ấy còn vang vọng. Người cầm tay, trao sự sống, và dặn cho em ăn: lòng thương rất cụ thể.", "The Lord says she is only asleep, takes her hand and says in Aramaic: “Talitha kum.” The Gospel keeps the original words as if still echoing. He takes her hand, gives life, and tells them to feed her: very concrete compassion.", "Chúa nói với những “điều đã chết” trong đời ta: “Hãy trỗi dậy”. Hãy để Người cầm tay nâng ta dậy.", "The Lord speaks to the “dead” parts of our life: “Arise.” Let him take your hand and lift you."]);
WORDS.push(["Mark", 6, 4, 4, "Ngôn sứ bị khinh ở quê hương", "A prophet without honour at home", "Dân Nadarét không tin vì thấy Chúa quen thuộc. Chúa nói ngôn sứ chỉ bị khinh ở quê hương, họ hàng, nhà mình. Tin Mừng nói Người không làm được phép lạ nào ở đó, và Người ngạc nhiên vì họ không tin. Đức tin mở đường cho Chúa hành động.", "The people of Nazareth do not believe because Jesus is familiar. He says a prophet is dishonoured only in his own country, among kin, in his own house. The Gospel says he could do no miracle there and marvelled at their unbelief. Faith opens the way for the Lord to act.", "Đừng coi thường điều quen thuộc như Thánh Thể, cha xứ, người nhà. Chính ở đó Chúa đang hoạt động.", "Do not take for granted what is familiar: Eucharist, pastor, family. There the Lord is at work."]);
WORDS.push(["Mark", 6, 8, 11, "Sai đi từng đôi, đi nhẹ", "Sent two by two, travelling light", "Chúa cho các môn đệ mang gậy, đi dép, không mang lương thực, túi, tiền. Họ đi từng đôi để làm chứng hỗ trợ nhau. Ở đâu được đón thì ở lại; bị từ chối thì phủi bụi chân làm chứng. Sứ giả là người sống nhờ Chúa và dựa vào lòng hiếu khách của người khác.", "The Lord lets the disciples take a staff and sandals but no bread, bag or money. They go two by two for mutual witness. Where welcomed stay; where refused shake off the dust as testimony. The messenger lives on God and on the hospitality of others.", "Truyền giáo không cần phương tiện lớn. Hãy dùng sự đơn sơ và đồng hành với nhau.", "Mission needs no great resources. Use simplicity and accompany each other."]);
WORDS.push(["Mark", 6, 31, 31, "Hãy đến nơi vắng vẻ mà nghỉ ngơi", "Come away and rest", "Các tông đồ trở về kể công việc. Chúa nhận ra họ mệt nên nói: hãy tách ra nơi hoang vắng nghỉ một chút. Đời sống tông đồ cần nghỉ ngơi và cầu nguyện. Chúa quan tâm sức khỏe của người phục vụ, không chỉ kết quả công việc.", "The apostles return reporting their work. The Lord sees they are tired and says: come away to a deserted place and rest a while. Apostolic life needs rest and prayer. He cares for the servant’s health, not just results.", "Hãy dành thời gian nghỉ ngơi thật sự và tĩnh lặng với Chúa. Nghỉ ngơi không phải là lười biếng.", "Take real rest and quiet with the Lord. Rest is not laziness."]);
WORDS.push(["Mark", 6, 37, 38, "Chính anh em hãy cho họ ăn", "You give them something to eat", "Các môn đệ nghĩ đến chuyện đi mua hai trăm bạc bánh. Chúa hỏi họ có bao nhiêu bánh và bảo đi xem. Họ có năm chiếc bánh và hai con cá. Chúa chọn dùng cái ít ỏi ta có để làm phép lạ; điều Người cần là ta dâng lên, không phải ta có đủ.", "The disciples think of buying two hundred denarii of bread. The Lord asks how many loaves they have and sends them to check. They have five loaves and two fish. The Lord chooses to use the little we have for his miracle; he needs us to offer, not to have enough.", "Hãy dâng cho Chúa điều nhỏ bé mình có và tin rằng Người nhân lên cho nhiều người.", "Offer the Lord the little you have and trust he multiplies it for many."]);
WORDS.push(["Mark", 6, 50, 50, "Can đảm lên, Thầy đây, đừng sợ", "Take heart, it is I; do not be afraid", "Chúa đi trên biển đến với các môn đệ đang vất vả chèo. Thấy Người, họ tưởng là ma và kêu lên. Người trấn an bằng ba câu: can đảm lên, Thầy đây, đừng sợ. “Thầy đây” nhắc lại cách Thiên Chúa tỏ mình. Chúa đến đúng lúc ta kiệt sức, và sự hiện diện của Người làm gió lặng.", "The Lord walks on the sea to the disciples straining at the oars. Seeing him they think it a ghost and cry out. He reassures in three phrases: take heart, it is I, do not be afraid. “It is I” echoes how God reveals himself. He comes when we are exhausted, and his presence calms the wind.", "Khi mệt mỏi vì chèo chống một mình, hãy nhận ra Chúa đang đến gần. Hãy mời Người lên thuyền cuộc đời.", "When exhausted from rowing alone, recognize the Lord approaching. Invite him into the boat of your life."]);
WORDS.push(["Mark", 7, 6, 13, "Dân này tôn kính Thầy bằng môi miệng", "This people honours me with their lips", "Chúa trích Isaia để vạch trần việc giữ truyền thống bề ngoài mà bỏ giới răn Thiên Chúa. Điển hình là lệ “Corban” cho phép khỏi phụng dưỡng cha mẹ vì đã khấn cúng cho Đền Thờ. Người nhắc điều răn thứ tư (thảo kính cha mẹ) và gọi đó là “làm cho lời Thiên Chúa trở nên vô hiệu”.", "The Lord quotes Isaiah to expose keeping outward tradition while abandoning God’s commandment. The typical case is “Corban,” allowing exemption from supporting parents because of a vow to the Temple. He recalls the fourth commandment (honour parents) and calls this “making void the word of God.”", "Chăm sóc cha mẹ già yếu là bổn phận hàng đầu. Đừng viện lý do bận việc đạo để né tránh.", "Caring for aging parents is a first duty. Do not cite church busyness to dodge it."]);
WORDS.push(["Mark", 7, 14, 23, "Điều từ trong ra làm ô uế", "What comes from within defiles", "Chúa gọi đám đông và nói điều từ ngoài vào không làm ô uế người ta; điều từ trong lòng ra mới làm ô uế. Khi ở riêng với các môn đệ, Người liệt kê mười hai điều xấu từ lòng: gian dâm, trộm cắp, giết người, tham lam, độc ác, gian dối, kiêu căng, điên rồ… Người tuyên bố mọi thức ăn đều thanh sạch, nhấn mạnh lòng người.", "The Lord calls the crowd and says what goes in from outside does not defile; what comes out of the heart does. Alone with his disciples he lists twelve evils from the heart: fornication, theft, murder, greed, malice, deceit, pride, folly… He declares all foods clean, stressing the human heart.", "Khi xét mình, hãy nhìn vào danh sách này. Mỗi lần có lời nói hay hành động xấu, hãy hỏi nó từ đâu đến và xin Chúa chữa lành gốc.", "In examination of conscience read this list. For each bad word or deed ask where it comes from and beg the Lord to heal the root."]);
WORDS.push(["Mark", 7, 27, 29, "Người phụ nữ Syrophênikê", "The Syrophoenician woman", "Chúa nói con cái phải được ăn no trước, không nên lấy bánh của con mà ném cho chó. Người phụ nữ ngoại giáo đáp lại bằng khiêm tốn và thông minh: chó dưới bàn cũng được ăn vụn bánh của con trẻ. Chúa khen lời đáp và chữa con gái bà. Lòng tin khiêm nhường bền bỉ chạm đến lòng Chúa.", "The Lord says the children must be fed first; it is not right to throw the children’s bread to dogs. The pagan woman answers humbly and wisely: even dogs under the table eat the children’s crumbs. The Lord praises the answer and heals her daughter. Humble, persistent faith touches his heart.", "Đừng bỏ cuộc khi lời cầu xin chưa được đáp ngay. Hãy kiên trì với đức tin khiêm tốn.", "Do not give up when a prayer is not answered at once. Persevere with humble faith."]);
WORDS.push(["Mark", 7, 34, 34, "Ephphatha: hãy mở ra", "Ephphatha: be opened", "Chúa chữa người điếc ngọng riêng ra khỏi đám đông, đặt ngón tay vào tai, chạm lưỡi, ngước mắt lên trời, thở dài và nói: “Ephphatha”. Từ ấy được giữ trong Nghi thức Rửa tội: xin Chúa mở tai để nghe Lời và mở miệng để tuyên xưng đức tin. Chữa lành đòi hỏi sự gần gũi.", "The Lord takes the deaf-mute apart from the crowd, puts fingers in his ears, touches his tongue, looks to heaven, sighs and says “Ephphatha.” This word is kept in the Rite of Baptism: asking God to open ears to hear the Word and mouth to proclaim faith. Healing takes closeness.", "Hãy xin Chúa mở tai nghe tiếng Người và mở miệng làm chứng. Cầu nguyện: “Ephphatha, xin mở lòng con”.", "Ask the Lord to open your ears to hear and your mouth to witness. Pray: “Ephphatha, open my heart.”"]);
WORDS.push(["Mark", 8, 2, 3, "Thầy thương đám đông", "I have compassion on the crowd", "Chúa nói Người thương đám đông đã ở với Người ba ngày không có gì ăn; nếu cho họ về đói thì sẽ lả dọc đường. Lòng thương xót của Chúa nhìn thấy nhu cầu cụ thể, nhỏ nhất, như cái đói. Người không bỏ họ cho đến khi họ ăn đủ.", "The Lord says he has compassion on the crowd with him three days and nothing to eat; sending them home hungry they would faint on the way. His compassion sees concrete small needs like hunger. He does not leave them until they are fed.", "Hãy nhìn nhu cầu nhỏ của người xung quanh: một bữa ăn, một lời hỏi han. Đó là chỗ lòng thương xót bắt đầu.", "See the small needs of those around you: a meal, a word of concern. That is where mercy begins."]);
WORDS.push(["Mark", 8, 12, 21, "Men của biệt phái và Hêrôđê", "The leaven of the Pharisees and Herod", "Chúa thở dài khi người ta đòi dấu lạ. Trên thuyền, môn đệ lo vì quên mang bánh. Chúa cảnh báo men của biệt phái và Hêrôđê rồi trách họ: mắt có mà không thấy, tai có mà không nghe. Người nhắc lại hai lần nhân bánh và hỏi “Anh em vẫn chưa hiểu sao?” Chúa muốn ta tin vào Người, không lo cho nhu cầu vật chất quá mức.", "The Lord sighs when asked for a sign. In the boat the disciples worry about forgetting bread. He warns of the leaven of the Pharisees and Herod then rebukes them: having eyes you do not see, ears you do not hear. He recalls the two multiplications and asks “Do you not yet understand?” The Lord wants us to trust him, not worry excessively about material needs.", "Nhìn lại những lần Chúa đã chăm sóc mình. Ký ức về ơn Chúa nuôi dưỡng niềm tin lúc lo lắng.", "Look back at times the Lord cared for you. Memory of his graces feeds trust in anxiety."]);
WORDS.push(["Mark", 8, 29, 33, "Phêrô tuyên xưng và bị quở", "Peter’s confession and rebuke", "Chúa hỏi “Anh em bảo Thầy là ai?” Phêrô đáp: Thầy là Đức Kitô. Chúa dặn đừng nói với ai, rồi lần đầu tiên nói về khổ nạn, cái chết và sống lại. Phêrô can ngăn thì Chúa quở: “Satan, hãy lui lại đằng sau Thầy, vì anh không nghĩ như Thiên Chúa mà như người phàm.” Thập giá là phần không thể thiếu của Đấng Cứu Thế.", "The Lord asks “Who do you say I am?” Peter: You are the Christ. He orders silence, then for the first time speaks of suffering, death and rising. When Peter objects he rebukes: “Get behind me, Satan, for you are not on the side of God but of men.” The cross is an indispensable part of the Messiah.", "Đừng muốn một Đức Kitô không thập giá. Hãy xin ơn nhìn thấy mọi điều theo cách của Chúa.", "Do not want a Christ without the cross. Ask grace to see everything God’s way."]);
WORDS.push(["Mark", 8, 34, 38, "Từ bỏ mình, vác thập giá", "Deny yourself and take up the cross", "Chúa mời cả đám đông và môn đệ: ai muốn theo Thầy thì hãy từ bỏ chính mình, vác thập giá mình mà theo. Ai muốn cứu mạng mình thì sẽ mất, ai mất mạng vì Thầy và Tin Mừng thì sẽ cứu được. “Được cả thế giới mà mất linh hồn thì lợi gì?” Người cũng cảnh báo: ai xấu hổ vì Người trước thế gian, Người cũng sẽ xấu hổ vì họ khi đến trong vinh quang.", "The Lord invites crowd and disciples: whoever wishes to follow me must deny himself, take up his cross and follow. Whoever saves his life will lose it; whoever loses it for me and the Gospel will save it. “What does it profit to gain the whole world and forfeit one’s soul?” He warns: whoever is ashamed of me before the world, I will be ashamed of when I come in glory.", "Mỗi ngày hãy chọn từ bỏ một điều cho chính mình để phục vụ người khác. Đừng xấu hổ khi làm dấu thánh giá hay cầu nguyện nơi công cộng.", "Each day choose to give up something for yourself to serve others. Do not be ashamed to make the sign of the cross or pray in public."]);
WORDS.push(["Mark", 9, 1, 1, "Có người ở đây sẽ không chết trước khi thấy Nước Thiên Chúa", "Some here will see the Kingdom come with power", "Lời này đứng ngay trước biến hình. Chúa hứa vài người sẽ được thấy Nước Thiên Chúa đến trong quyền năng: các tông đồ được thoáng thấy vinh quang Người trên núi, và sau đó thấy Phục Sinh và Hội Thánh lớn lên. Vinh quang không chỉ ở đời sau mà đã bắt đầu từ hôm nay.", "This saying stands right before the Transfiguration. The Lord promises some will see the Kingdom come with power: the apostles glimpse his glory on the mountain, and later the Resurrection and the Church’s growth. Glory is not only for the next life but begins today.", "Hãy mở mắt nhận ra dấu hiệu Nước Chúa đang lớn lên quanh mình: một lần hòa giải, một lần giúp đỡ, một người trở lại.", "Open your eyes to signs of the Kingdom growing around you: a reconciliation, an act of help, a person’s return."]);
WORDS.push(["Mark", 9, 11, 12, "Êlia phải đến trước", "Elijah must come first", "Các môn đệ hỏi vì sao kinh sư nói Êlia phải đến trước. Chúa xác nhận Êlia đến để sửa soạn mọi sự, nhưng đã đến rồi và người ta xử với ông như ý muốn. Người dùng điều đó để nhắc rằng Con Người cũng phải chịu nhiều đau khổ và bị khinh. Con đường của sứ giả và của Đấng Cứu Thế đều là đường khổ nạn.", "The disciples ask why scribes say Elijah must come first. The Lord confirms Elijah comes to restore all things but has already come and been treated as they pleased. He uses this to recall that the Son of Man must also suffer much and be despised. The way of the herald and the Messiah is the way of suffering.", "Đừng ngạc nhiên khi làm điều tốt mà bị hiểu lầm. Hãy nhớ các ngôn sứ và chính Chúa cũng thế.", "Do not be surprised when doing good brings misunderstanding. Remember the prophets and the Lord himself."]);
WORDS.push(["Mark", 9, 18, 19, "Hỡi thế hệ cứng lòng tin", "O faithless generation", "Các môn đệ không chữa được em bé bị quỷ câm. Chúa thở dài: “Hỡi thế hệ cứng lòng tin, Thầy còn ở với các con đến bao giờ?” Lời trách nhắm cả cha em bé, đám đông, các môn đệ. Rồi Người nói “Đem nó lại đây cho Thầy”: Chúa vẫn muốn giúp dù ta kém tin.", "The disciples cannot cure the boy with a mute spirit. The Lord sighs: “O faithless generation, how long am I to be with you?” The rebuke is aimed at the father, crowd and disciples. Then he says “Bring him to me”: he still wants to help despite our lack of faith.", "Dù thấy đức tin mình yếu, hãy mang vấn đề đến cho Chúa. Người vẫn nói: “Đem nó lại đây cho Thầy.”", "Even if your faith seems weak, bring the problem to the Lord. He still says: “Bring him to me.”"]);
WORDS.push(["Mark", 9, 22, 28, "Tôi tin, xin Chúa giúp lòng tin yếu kém của tôi", "I believe; help my unbelief", "Người cha cầu xin: “Nếu Thầy làm được gì, xin thương giúp chúng tôi.” Chúa đáp: “Nếu Thầy làm được ư? Ai tin thì mọi sự đều có thể.” Người cha kêu lên: “Tôi tin, xin giúp lòng kém tin của tôi.” Lời cầu nguyện chân thật nhất của người tin. Chúa trục xuất quỷ và nói loại này chỉ ra được bằng cầu nguyện.", "The father pleads: “If you can do anything, have pity on us.” The Lord answers: “‘If you can’? All things are possible to him who believes.” The father cries: “I believe; help my unbelief.” The most honest prayer of a believer. The Lord casts out the spirit and says this kind comes out only by prayer.", "Hãy dùng lời cầu: “Lạy Chúa, con tin, xin giúp lòng kém tin của con”, nhất là khi nghi ngờ.", "Use the prayer: “Lord, I believe; help my unbelief,” especially in doubt."]);
WORDS.push(["Mark", 9, 30, 31, "Báo trước khổ nạn lần hai", "Second Passion prediction", "Chúa dạy riêng các môn đệ: Con Người sẽ bị nộp vào tay người ta, bị giết, ba ngày sau sẽ sống lại. Họ không hiểu và sợ không dám hỏi. Chúa kiên nhẫn lặp lại để họ quen với điều ngoài mong đợi: cứu độ bằng thập giá.", "The Lord teaches the disciples privately: the Son of Man will be delivered into men’s hands, killed, and after three days rise. They do not understand and fear to ask. He patiently repeats so they accustom to the unexpected: salvation by the cross.", "Đừng ngại hỏi Chúa khi chưa hiểu. Hãy mang thắc mắc đức tin đến linh mục, giáo lý, và cầu nguyện.", "Do not fear asking the Lord when you do not understand. Bring faith questions to a priest, catechism and prayer."]);
WORDS.push(["Mark", 9, 34, 36, "Ai làm đầu thì làm người phục vụ mọi người", "The first must be servant of all", "Dọc đường các môn đệ tranh luận ai lớn nhất; Chúa im lặng chờ họ xấu hổ rồi nói: ai muốn đứng đầu phải làm người rốt hết và làm đầy tớ mọi người. Người ôm một em nhỏ và nói: ai đón nhận một em bé nhân danh Thầy là đón Thầy và đón Đấng đã sai Thầy. Người bé nhỏ là trung tâm của Nước Trời.", "On the road the disciples argued who was greatest; the Lord waited in silence for them to be ashamed, then said: whoever wants to be first must be last of all and servant of all. He embraces a child: whoever receives one such child in my name receives me and the One who sent me. The little one is the heart of the Kingdom.", "Hãy đón tiếp người nhỏ bé, như trẻ em, người nghèo, người cô đơn, bằng tình cảm thật và thời gian.", "Welcome the little ones such as children, the poor and lonely with real affection and time."]);
WORDS.push(["Mark", 9, 38, 41, "Ai không chống lại chúng ta là thuận với chúng ta", "Whoever is not against us is for us", "Gioan muốn cấm người lạ nhân danh Chúa trừ quỷ vì “không theo chúng ta”. Chúa nói đừng cấm: ai làm việc nhân danh Người không thể nói xấu Người liền sau đó. Chén nước lã cho người thuộc về Đức Kitô cũng không mất phần thưởng. Ơn Chúa lớn hơn ranh giới nhóm của ta.", "John wants to forbid a stranger casting out demons in his name because “he does not follow us.” The Lord says do not forbid: no one who works a miracle in his name can soon speak ill of him. A cup of water to one belonging to Christ will not lose its reward. God’s grace is larger than our group lines.", "Hãy mừng khi người khác làm điều tốt, kể cả ngoài nhóm hay giáo xứ của mình. Đừng ghen tị trong việc tông đồ.", "Rejoice when others do good, even outside your group or parish. Do not be jealous in apostolate."]);
WORDS.push(["Mark", 9, 42, 49, "Đừng làm gương xấu; hãy cắt bỏ điều dẫn đến tội", "Do not scandalize; cut off what leads to sin", "Chúa dùng ngôn ngữ rất mạnh: thà bị buộc cối đá quăng xuống biển còn hơn làm cho một trẻ nhỏ mất đức tin. Tay, chân, mắt gây vấp phạm thì cắt bỏ, vì vào đời sống thiếu một chi vẫn hơn vào hỏa ngục. Người nhắc lại hình ảnh “giòi bọ không chết” và “lửa không tắt”. Lời cuối: “Muối là tốt”; hãy giữ muối trong mình và sống hòa thuận.", "The Lord uses very strong language: better a millstone and the sea than causing a little one to lose faith. Hand, foot or eye that causes sin should be cut off, for it is better to enter life maimed than whole into hell. He recalls “the worm that does not die” and “the fire that is not quenched.” Last words: “Salt is good”; have salt in yourselves and be at peace.", "Hãy chọn dứt khoát loại bỏ thứ gây sa ngã (mối quan hệ, mạng xã hội, thói quen). Giữ “muối” của đức tin để sống hòa thuận.", "Decisively remove what causes you to fall (relationships, media, habits). Keep the “salt” of faith to live in peace."]);
WORDS.push(["Mark", 10, 3, 9, "Điều Thiên Chúa đã kết hợp", "What God has joined", "Chúa hỏi Môsê truyền gì, rồi nói Môsê cho ly dị vì lòng chai dạ đá. Từ lúc tạo dựng, Thiên Chúa làm nên nam và nữ; người nam rời cha mẹ, kết hợp với vợ, hai người thành một thân xác. Điều Chúa đã phối hợp, loài người không được tách rời. Hôn nhân là ân huệ từ Chúa và bền vững.", "The Lord asks what Moses commanded, then says Moses permitted divorce because of hardness of heart. From creation God made male and female; a man leaves his parents and cleaves to his wife, and the two become one flesh. What God has joined, let no one separate. Marriage is a gift from God and permanent.", "Vợ chồng hãy cầu nguyện cùng nhau mỗi ngày và xin ơn trung thành. Nếu gặp khó khăn, hãy tìm giúp đỡ sớm.", "Spouses pray together daily and ask fidelity. If in difficulty seek help early."]);
WORDS.push(["Mark", 10, 11, 12, "Ngoại tình và tái hôn", "Adultery and remarriage", "Trong nhà, các môn đệ hỏi lại; Chúa nói rõ: ai bỏ vợ mà cưới người khác là phạm tội ngoại tình, và nếu người vợ bỏ chồng cưới người khác cũng thế. Marcô nhấn mạnh sự công bằng giữa nam nữ trong hôn nhân: cả hai đều phải trung thành, đều có phẩm giá ngang nhau.", "In the house the disciples ask again; the Lord is clear: whoever divorces his wife and marries another commits adultery against her, and if she divorces her husband and marries another she commits adultery. Mark stresses equality of man and woman in marriage: both must be faithful, both of equal dignity.", "Hãy tôn trọng vợ/chồng như người bình đẳng và tận tâm với họ. Nếu có hoàn cảnh phức tạp, hãy tìm sự đồng hành của Hội Thánh.", "Respect spouse as equal and be devoted. In complex situations seek the Church’s accompaniment."]);
WORDS.push(["Mark", 10, 14, 15, "Để trẻ em đến với Thầy", "Let the children come to me", "Chúa bực mình khi môn đệ ngăn trẻ nhỏ. Người nói: để chúng đến, vì Nước Thiên Chúa thuộc về những kẻ như chúng. Ai không đón nhận Nước Thiên Chúa như trẻ nhỏ thì không vào được. Trẻ em nhận quà mà không đòi công trạng: mẫu mực của ơn cứu độ.", "The Lord is indignant when disciples hinder children. He says: let them come, for the Kingdom belongs to such as these. Whoever does not receive the Kingdom like a child will not enter it. A child receives a gift without claiming merit: the model of salvation.", "Hãy đón nhận Chúa như quà tặng, không phải phần thưởng. Hãy dạy con trẻ cầu nguyện từ bé.", "Receive God as gift, not reward. Teach children to pray from small."]);
WORDS.push(["Mark", 10, 18, 21, "Chàng thanh niên giàu có", "The rich young man", "Anh hỏi “Thầy nhân lành, con phải làm gì?” Chúa đáp “Sao anh gọi tôi là nhân lành? Không ai nhân lành trừ một mình Thiên Chúa”. Rồi Người nêu các điều răn. Marcô ghi: Chúa nhìn anh và thương, và nói: còn thiếu một điều, hãy bán đi tất cả, cho người nghèo, rồi đến theo Thầy. Lời mời nên trọn vẹn xuất phát từ tình yêu.", "He asks “Good Teacher, what must I do?” The Lord replies “Why do you call me good? No one is good but God alone.” Then he names the commandments. Mark notes: Jesus looked at him and loved him and said: you lack one thing; sell all, give to the poor, then follow me. The invitation to fullness arises from love.", "Mọi lời mời của Chúa đến từ tình yêu. Hãy tin rằng điều Chúa xin ở ta là để ta được tự do và hạnh phúc.", "Every invitation from the Lord comes from love. Trust that what he asks is for your freedom and happiness."]);
WORDS.push(["Mark", 10, 23, 27, "Người giàu khó vào Nước Trời", "How hard for the rich", "Chúa nhìn quanh nói người giàu khó vào Nước Thiên Chúa. Môn đệ kinh ngạc; Người nói lại “Các con ơi, khó thay”, và “lạc đà chui qua lỗ kim”. Họ hỏi ai cứu được? Chúa nhìn họ: “Đối với loài người thì không thể, nhưng đối với Thiên Chúa thì không. Mọi sự đều có thể.” Cứu độ là ân huệ.", "The Lord looks around and says it is hard for the rich to enter the Kingdom. The disciples are astonished; he says again “Children, how hard,” and “a camel through the eye of a needle.” They ask who can be saved? Looking at them: “With men it is impossible, but not with God; all things are possible with God.” Salvation is grace.", "Dù ta giàu hay nghèo, ơn cứu độ không do mua được. Hãy sống đơn giản và hào phóng.", "Rich or poor, salvation cannot be bought. Live simply and generously."]);
WORDS.push(["Mark", 10, 29, 31, "Gấp trăm kèm bách hại", "A hundredfold with persecutions", "Chúa hứa ai bỏ nhà cửa, anh em, cha mẹ, con cái, ruộng đất vì Người và vì Tin Mừng sẽ nhận gấp trăm ngay đời này, kèm cả bách hại, và đời sau sự sống đời đời. Marcô thêm hai chữ “kèm bách hại”: ơn Chúa không loại trừ đau khổ. Rồi Người nói kẻ trước nên sau, kẻ sau nên trước.", "The Lord promises whoever leaves house, brothers, parents, children or fields for him and the Gospel will receive a hundredfold now, with persecutions, and in the age to come eternal life. Mark adds “with persecutions”: God’s gifts do not exclude suffering. Then: the first will be last and the last first.", "Theo Chúa có giá, nhưng phần thưởng lớn hơn nhiều. Hãy sống hy sinh với niềm hy vọng.", "Following the Lord has a price, but the reward is far greater. Live sacrifice in hope."]);
WORDS.push(["Mark", 10, 33, 34, "Báo trước khổ nạn lần ba", "Third Passion prediction", "Trên đường lên Giêrusalem, Chúa đi trước và các môn đệ kinh ngạc, theo sau mà sợ hãi. Người nói chi tiết: bị nộp, bị lên án, bị chế nhạo, nhổ vào mặt, đánh đòn, giết, ba ngày sau sống lại. Chúa biết rõ nhưng vẫn đi trước, tự nguyện. Ta theo Người trên con đường ấy.", "On the road up to Jerusalem the Lord walks ahead; the disciples are amazed and follow afraid. He speaks in detail: delivered, condemned, mocked, spat upon, scourged, killed, and after three days rise. He knows yet goes ahead, freely. We follow him on that road.", "Khi con đường theo Chúa trở nên khó, hãy nhớ Người đi trước ta. Ta không đi một mình.", "When the way of following the Lord grows hard, remember he goes before you. You do not walk alone."]);
WORDS.push(["Mark", 10, 36, 40, "Chén Thầy uống, phép rửa Thầy chịu", "The cup I drink, the baptism I undergo", "Hai anh em Giacôbê và Gioan xin ngồi bên hữu bên tả Chúa trong vinh quang. Chúa đáp: các anh không biết điều mình xin; có uống nổi chén Thầy uống, chịu nổi phép rửa Thầy chịu không? Họ nói “được”. Chúa nói họ sẽ uống nhưng chỗ ngồi là Cha chuẩn bị. Vinh quang đi qua đau khổ.", "James and John ask to sit at his right and left in glory. The Lord replies: you do not know what you ask; can you drink the cup I drink or be baptized with the baptism I am baptized with? They say “We can.” He says they will but the seats are prepared by the Father. Glory passes through suffering.", "Đừng xin vinh quang mà không muốn thập giá. Hãy xin ơn để theo Chúa đến cùng.", "Do not ask for glory without the cross. Ask grace to follow the Lord to the end."]);
WORDS.push(["Mark", 10, 42, 45, "Ai muốn làm lớn thì làm người phục vụ", "Whoever wishes to be great must serve", "Các thủ lãnh dân ngoại thống trị và dùng quyền lực. Chúa nói giữa anh em không được thế: ai muốn làm lớn hãy làm người phục vụ, ai muốn đứng đầu hãy làm đầy tớ mọi người. Câu kết là lời lớn nhất: Con Người đến để phục vụ và hiến mạng sống làm giá chuộc nhiều người. Tin Mừng Máccô gói trong câu này.", "Gentile rulers lord it over and use power. The Lord says not so among you: whoever wants to be great must be your servant, whoever wants to be first must be slave of all. The last line is the greatest: the Son of Man came to serve and give his life as a ransom for many. Mark’s Gospel is summed up in this line.", "Hãy hỏi mỗi ngày: tôi đã phục vụ ai hôm nay? Quyền lực thật của Kitô hữu là tình yêu hiến thân.", "Ask each day: whom did I serve today? True Christian power is self-giving love."]);
WORDS.push(["Mark", 10, 49, 52, "Anh muốn Thầy làm gì cho anh?", "What do you want me to do for you?", "Ông Bartimê ngồi ăn xin ven đường, kêu lên “Lạy Con Vua Đavít, xin thương xót tôi”. Người ta bảo ông im, ông càng kêu to. Chúa dừng lại và nói “Hãy gọi ông ấy”. Ông vứt áo choàng, nhảy lên chạy đến. Chúa hỏi “Anh muốn Thầy làm gì?” “Thưa Thầy, xin cho tôi được thấy.” “Hãy đi, đức tin anh đã cứu anh.” Ông liền thấy và theo Chúa trên đường.", "Bartimaeus sits begging by the road and cries “Son of David, have mercy on me.” People tell him to be quiet; he cries louder. The Lord stops and says “Call him.” He throws off his cloak, leaps up and comes. The Lord asks “What do you want me to do?” “Master, let me receive my sight.” “Go your way; your faith has made you well.” He sees and follows Jesus on the road.", "Hãy kêu xin kiên trì, bỏ “áo choàng” (điều ta bám víu), và dám nói ra điều mình xin. Rồi theo Chúa.", "Cry persistently, cast off your “cloak” (what you cling to) and dare to say what you ask. Then follow the Lord."]);
WORDS.push(["Mark", 11, 2, 3, "Hãy tìm con lừa non", "Find the colt", "Chúa sai hai môn đệ đi lấy con lừa chưa ai cưỡi, nói: “Chúa cần đến nó”. Người vào Giêrusalem khiêm tốn trên lừa con, ứng nghiệm lời Dacaria: vua hiền lành. Quyền của Chúa không bằng vũ lực nhưng bằng hiền lành. Chúa chỉ xin những điều nhỏ của ta, như con lừa.", "The Lord sends two disciples for a colt no one has ridden, saying “The Lord has need of it.” He enters Jerusalem humbly on a colt, fulfilling Zechariah’s humble king. The Lord’s power is not by force but gentleness. He asks small things of us like the colt.", "“Chúa cần đến nó”: Chúa cần thời gian, tài năng nhỏ bé của tôi. Hãy trả lời “vâng” cho một lời mời nhỏ.", "“The Lord has need of it”: the Lord needs my time, my small gifts. Say “yes” to a small invitation."]);
WORDS.push(["Mark", 11, 14, 17, "Cây vả và Đền Thờ", "The fig tree and the Temple", "Chúa đói đến cây vả chỉ có lá và quở: “Đừng ai ăn trái của ngươi nữa”. Marcô kẹp việc thanh tẩy Đền Thờ vào giữa: cây vả không trái giống đền thờ không sinh hoa trái. Chúa trích Isaia: nhà Ta là nhà cầu nguyện cho mọi dân tộc, nhưng các ông biến thành hang trộm. Lời cầu nguyện cho mọi dân bị bỏ quên.", "Hungry, the Lord finds a fig tree with only leaves and says: “May no one eat fruit from you again.” Mark sandwiches the cleansing of the Temple in between: the leafy fig tree resembles a temple without fruit. He quotes Isaiah: my house shall be a house of prayer for all nations, but you made it a den of robbers. Prayer for all nations was forgotten.", "Hãy làm cho giáo xứ và gia đình mình thành nơi cầu nguyện và đón nhận mọi người. Đừng biến đạo thành việc kinh doanh.", "Make your parish and family a place of prayer and welcome for all. Do not make religion a business."]);
WORDS.push(["Mark", 11, 22, 26, "Hãy tin vào Thiên Chúa; cầu nguyện và tha thứ", "Have faith in God; prayer and forgiveness", "Sáng hôm sau cây vả khô. Chúa dạy: hãy có đức tin vào Thiên Chúa; ai nói với núi này “hãy nhổ lên mà quăng xuống biển” mà không nghi ngờ thì sẽ được. Mọi điều anh em xin khi cầu nguyện, hãy tin đã được rồi. Và khi đứng cầu nguyện, nếu có điều gì với ai thì hãy tha để Cha trên trời cũng tha lỗi cho anh em.", "Next morning the fig tree is withered. The Lord teaches: have faith in God; whoever says to this mountain “be taken up and cast into the sea” without doubting will have it. Whatever you ask in prayer, believe you have received it. And when you stand praying, if you have anything against anyone, forgive so your Father may forgive you.", "Cầu nguyện cần hai điều: đức tin và lòng tha thứ. Trước khi xin Chúa, hãy tha cho người đã làm mình tổn thương.", "Prayer needs two things: faith and forgiveness. Before asking God, forgive those who hurt you."]);
WORDS.push(["Mark", 11, 29, 33, "Quyền bính của Chúa từ đâu?", "By what authority?", "Các thượng tế hỏi Chúa lấy quyền gì làm các việc đó. Chúa hỏi lại về phép rửa của Gioan: bởi trời hay bởi người? Họ tính toán và nói không biết. Chúa nói Người cũng không nói. Họ không tìm sự thật mà sợ dân chúng; vì thế không thể nhận ra thẩm quyền của Chúa.", "The chief priests ask by what authority he does these things. He asks in return about John’s baptism: from heaven or from men? They calculate and say they do not know. The Lord says neither will he say. They do not seek truth but fear the people; thus they cannot recognize his authority.", "Hãy tìm sự thật chứ không tìm sự an toàn. Sự thật đôi khi cần lòng can đảm.", "Seek truth, not safety. Truth sometimes needs courage."]);
WORDS.push(["Mark", 12, 1, 11, "Dụ ngôn vườn nho và hòn đá góc", "The vineyard parable and the cornerstone", "Chủ vườn nho sai nhiều tôi tớ đến, người bị đánh, người bị giết, cuối cùng sai con yêu quý: “Chúng sẽ nể con ta”. Nhưng họ giết cả con. Chúa trích Thánh vịnh 118: hòn đá thợ xây loại bỏ đã nên đá góc. Đây là lịch sử cứu độ: Thiên Chúa kiên nhẫn sai các ngôn sứ rồi Con Một, và Người Con ấy chịu chết rồi sống lại để thành nền Hội Thánh.", "The vineyard owner sends servants, some beaten, some killed; last he sends his beloved son: “They will respect my son.” But they kill the son. The Lord quotes Psalm 118: the stone the builders rejected has become the cornerstone. This is salvation history: God patiently sends prophets then his only Son, who dies and rises to become the Church’s foundation.", "Chúa kiên nhẫn chờ ta sinh hoa trái. Hãy đón nhận “người được sai đến”, và nhớ rằng đá góc của đời ta là Đức Kitô.", "The Lord patiently waits for fruit from us. Welcome those sent and remember Christ is the cornerstone of our life."]);
WORDS.push(["Mark", 12, 15, 17, "Của Xêda trả Xêda", "Render to Caesar", "Họ cố gài bẫy về thuế. Chúa xin một đồng bạc, hỏi hình ảnh của ai rồi nói trả cho Xêda của Xêda và trả cho Thiên Chúa của Thiên Chúa. Chúng ta mang hình ảnh Thiên Chúa; trả cho Người chính là hiến dâng cả đời ta. Họ kinh ngạc về Người.", "They try to trap him about taxes. The Lord asks for a coin, whose image, then says give to Caesar what is Caesar’s and to God what is God’s. We bear God’s image; giving to God is offering our whole life. They marvel at him.", "Hãy làm bổn phận công dân nghiêm túc nhưng đừng để nó thay chỗ Thiên Chúa. Hãy dâng chính mình cho Người.", "Do civic duty seriously but do not let it replace God. Offer yourself to him."]);
WORDS.push(["Mark", 12, 24, 27, "Thiên Chúa của kẻ sống", "The God of the living", "Các Sađốc hỏi về người phụ nữ lấy bảy anh em. Chúa nói họ lầm vì không hiểu Kinh Thánh và quyền năng Thiên Chúa; khi sống lại người ta như thiên thần. Người dẫn bụi gai cháy: Thiên Chúa của Ápraham, Ixaác, Giacóp là Thiên Chúa của kẻ sống. Mối tương quan với Chúa không bị cái chết cắt đứt.", "The Sadducees ask about the woman with seven husbands. The Lord says they are wrong, not understanding Scripture or God’s power; in the resurrection people are like angels. He cites the burning bush: the God of Abraham, Isaac and Jacob is God of the living. A relationship with God is not cut by death.", "Tin vào sự sống lại giúp ta sống hy vọng và không sợ cái chết. Hãy cầu nguyện cho người đã khuất như những người đang sống trong Chúa.", "Faith in resurrection helps us live in hope without fear of death. Pray for the departed as those alive in God."]);
WORDS.push(["Mark", 12, 29, 31, "Điều răn thứ nhất và thứ hai", "The first and second commandments", "Chúa trích “Nghe đây, hỡi Ítraen: Đức Chúa là Thiên Chúa của chúng ta là Đức Chúa duy nhất” và dạy mến Chúa hết lòng, hết linh hồn, hết trí khôn, hết sức lực. Điều răn thứ hai: yêu người thân cận như chính mình. Không có điều răn nào lớn hơn hai điều này. Tin Mừng gói trong hai tình yêu không thể tách rời.", "The Lord quotes “Hear, O Israel: the Lord our God, the Lord is one” and teaches loving God with all heart, soul, mind and strength. The second commandment: love your neighbour as yourself. There is no commandment greater than these. The Gospel is wrapped in two inseparable loves.", "Hãy cầu nguyện đọc “Nghe đây, hỡi Ítraen” và chọn một hành động cụ thể yêu người thân cận hôm nay.", "Pray the “Hear, O Israel” and choose one concrete act of love of neighbour today."]);
WORDS.push(["Mark", 12, 34, 34, "Ông không xa Nước Thiên Chúa", "You are not far from the Kingdom", "Một kinh sư khen Chúa trả lời đúng và nhắc rằng yêu mến Chúa và người còn hơn mọi lễ vật. Chúa thấy ông trả lời khôn ngoan và nói: “Ông không xa Nước Thiên Chúa.” Gần nhưng chưa vào: còn một bước, theo Chúa. Lời khen của Chúa là lời mời tiến thêm.", "A scribe commends the Lord’s answer and adds that loving God and neighbour is more than all offerings. The Lord sees he answered wisely and says: “You are not far from the Kingdom of God.” Near but not yet in: one step remains, following him. The Lord’s praise is an invitation to go further.", "Hiểu biết đúng chưa đủ, hãy bước thêm một bước, đến sống với Chúa. Hãy hỏi mình còn thiếu bước nào.", "Right understanding is not enough; take one more step to live with the Lord. Ask which step you lack."]);
WORDS.push(["Mark", 12, 35, 37, "Đức Kitô có phải chỉ là con Đavít?", "Is the Christ merely David’s son?", "Chúa hỏi vì sao kinh sư nói Đức Kitô là con Đavít, trong khi chính Đavít, được Thánh Thần linh hứng, gọi Người là Chúa. Vậy Người vừa là hậu duệ vừa cao hơn Đavít. Đám đông thích nghe Chúa. Lời hỏi mở ra mầu nhiệm thiên tính của Đấng Cứu Thế.", "The Lord asks why scribes say the Christ is David’s son when David himself, inspired by the Spirit, calls him Lord. So he is both descendant and greater than David. The great crowd listens with delight. The question opens the mystery of the Messiah’s divinity.", "Hãy tìm hiểu để biết Chúa Giêsu là ai, vừa là Con Người vừa là Con Thiên Chúa, và để mầu nhiệm ấy làm lòng ta thờ lạy.", "Seek to know who Jesus is, Son of Man and Son of God, and let that mystery move your heart to worship."]);
WORDS.push(["Mark", 12, 38, 40, "Coi chừng các kinh sư", "Beware of the scribes", "Chúa cảnh báo: các kinh sư thích mặc áo dài đi lại, được chào ở chợ, ngồi ghế đầu, và nuốt nhà các bà góa rồi cầu nguyện dài để làm bộ. Họ sẽ bị án nặng hơn. Tôn giáo dùng để phô trương và lợi dụng người yếu là điều Chúa lên án nặng nhất.", "The Lord warns: scribes like to walk in long robes, be greeted in markets, take the best seats, devour widows’ houses and make long prayers for show. They will receive greater condemnation. Religion used for display and exploiting the weak is what he condemns most.", "Hãy hỏi: tôi có làm điều đạo đức để được tôn trọng không? Đừng bao giờ lợi dụng chức vụ hay danh tiếng đạo đức.", "Ask: do I do religious acts to be respected? Never exploit office or religious reputation."]);
WORDS.push(["Mark", 12, 43, 44, "Đồng tiền của bà góa", "The widow’s mite", "Chúa ngồi đối diện thùng tiền và gọi môn đệ: bà góa nghèo bỏ vào hai đồng tiền kẽm, nhiều hơn mọi người, vì người ta bỏ của dư, bà bỏ cả những gì để sống. Chúa không nhìn số lượng mà nhìn lòng. Của lễ là sự trao ban chính mình.", "The Lord sits opposite the treasury and calls disciples: the poor widow put in two small coins, more than all, for others gave from abundance, she gave all she had to live on. The Lord looks not at quantity but at the heart. The offering is the gift of self.", "Hãy dâng cho Chúa không chỉ phần dư mà cả điều quý giá của mình: thời gian, hy sinh. Chúa thấy từng cử chỉ nhỏ.", "Offer the Lord not only surplus but what is precious: time, sacrifice. The Lord sees each small gesture."]);
WORDS.push(["Mark", 13, 2, 2, "Sẽ không còn hòn đá nào trên hòn đá nào", "Not one stone left upon another", "Khi môn đệ khoe vẻ lộng lẫy Đền Thờ, Chúa nói tất cả sẽ bị phá. Mọi công trình dù đẹp đều tạm thời, chỉ Nước Chúa tồn tại. Đây là dẫn nhập cho bài giảng về thời cuối.", "When the disciples admire the Temple’s splendour, the Lord says all will be thrown down. All human structures, however beautiful, are temporary; only God’s Kingdom endures. This introduces the discourse on the end times.", "Đừng gắn bó với điều tạm bợ. Hãy đặt hy vọng vào điều không qua đi.", "Do not attach to the transient. Place hope in what does not pass."]);
WORDS.push(["Mark", 13, 5, 13, "Coi chừng kẻo bị lừa; bền đỗ đến cùng", "Watch out lest you be deceived; endure to the end", "Chúa nói khi chiến tranh, động đất, đói kém thì “đừng hoảng sợ, đó mới là khởi đầu cơn đau đẻ”. Các môn đệ sẽ bị bách hại, nhưng Thánh Thần sẽ nói thay họ. Anh em phản anh em; mọi người ghét các con vì danh Thầy. Ai bền đỗ đến cùng sẽ được cứu. Tin Mừng phải được loan báo cho mọi dân tộc.", "The Lord says when wars, earthquakes and famines come “do not be alarmed, this is only the beginning of birth pangs.” The disciples will be persecuted but the Spirit will speak for them. Brother betrays brother; all hate you for my name’s sake. Whoever endures to the end will be saved. The Gospel must be proclaimed to all nations.", "Đừng để tin xấu làm mất bình an. Hãy bền đỗ trong bổn phận và giữ đức tin; Thánh Thần luôn ở cùng.", "Do not let bad news steal peace. Persevere in duty and keep faith; the Spirit is always with you."]);
WORDS.push(["Mark", 13, 14, 23, "Đại nạn và những ngôn sứ giả", "The great tribulation and false prophets", "Chúa nói về “vật ghê tởm hoang tàn”, báo hiệu Giêrusalem sắp bị tàn phá: ai ở Giuđê hãy chạy lên núi, chớ quay lại. Cầu nguyện cho khỏi mùa đông và ngày sabát. Sẽ có Kitô giả và ngôn sứ giả làm dấu lạ để lừa cả người được chọn. Chúa kết: “Hãy coi chừng, Thầy đã báo trước mọi điều.”", "The Lord speaks of the “abomination of desolation” signalling Jerusalem’s coming destruction: those in Judea flee to the mountains, not turning back. Pray it not be in winter or on the Sabbath. False Christs and prophets will work signs to deceive even the elect. He concludes: “Take heed; I have told you all things beforehand.”", "Hãy bám vào giáo huấn Hội Thánh để không bị lừa bởi “dấu lạ” và các tiên tri giả. Chúa đã báo trước để ta tỉnh táo.", "Hold to the Church’s teaching so as not to be deceived by “signs” and false prophets. The Lord forewarned that we may be alert."]);
WORDS.push(["Mark", 13, 24, 27, "Con Người đến trong vinh quang", "The Son of Man will come in glory", "Sau cơn đại nạn mặt trời tối, mặt trăng hết sáng, các vì sao rơi. Bấy giờ người ta sẽ thấy Con Người ngự trong mây với đầy quyền năng và vinh quang. Người sai thiên thần tụ họp những người được chọn từ bốn phương. Lịch sử có đích đến: Đức Kitô trở lại.", "After the tribulation the sun darkens, the moon gives no light, the stars fall. Then they will see the Son of Man coming in clouds with great power and glory. He sends angels to gather the elect from the four winds. History has a destination: Christ’s return.", "Hãy sống với niềm hy vọng chờ ngày Chúa đến: không sợ, nhưng tỉnh thức.", "Live with hope awaiting the Lord’s day: not in fear but vigilant."]);
WORDS.push(["Mark", 13, 28, 31, "Cây vả và lời Thầy không qua đi", "The fig tree and my words will not pass away", "Khi thấy cành cây vả nảy lộc, ta biết mùa hè gần. Khi thấy các điều ấy xảy ra, biết rằng Người đã gần đến ngay cửa. Chúa còn nói: “Trời đất sẽ qua đi, nhưng lời Thầy sẽ không qua đi.” Lời Chúa là điểm tựa vững chắc nhất giữa bất ổn.", "When the fig tree’s branch buds we know summer is near. When you see these things know he is near, at the very gates. He adds: “Heaven and earth will pass away, but my words will not pass away.” God’s word is the surest anchor amid instability.", "Hãy chọn Lời Chúa làm la bàn khi thế giới thay đổi nhanh. Đọc mỗi ngày một đoạn Tin Mừng.", "Choose God’s word as compass when the world changes fast. Read one Gospel passage daily."]);
WORDS.push(["Mark", 13, 32, 37, "Hãy canh thức", "Be on guard; stay awake", "Không ai biết ngày giờ, kể cả các thiên thần và Con; chỉ Cha biết. Chúa so sánh với người chủ đi xa giao cho tôi tớ mỗi người việc của mình và người giữ cửa phải canh thức. Không biết chủ về lúc nào: chiều, nửa đêm, gà gáy hay sáng sớm. “Điều Thầy nói với anh em, Thầy nói với mọi người: hãy canh thức.”", "No one knows the day or hour, not angels nor the Son, only the Father. The Lord compares a master who goes away giving each servant his task and telling the doorkeeper to watch. They do not know when he returns: evening, midnight, cockcrow or morning. “What I say to you I say to all: Watch.”", "Canh thức là sống trung thành từng ngày: làm việc của mình, cầu nguyện, sẵn sàng. Hãy dành vài phút cuối ngày để xét mình.", "Watchfulness is faithful daily living: doing your task, praying, being ready. Take a few minutes at day’s end for examination."]);
WORDS.push(["Mark", 14, 6, 9, "Bà đã làm việc tốt cho Thầy", "She has done a beautiful thing", "Người ta chê việc dùng dầu thơm quý là phí. Chúa bảo đừng làm khó bà: bà đã làm việc tốt cho Thầy; người nghèo luôn có với anh em, còn Thầy không luôn ở đây. Bà xức dầu trước cho việc mai táng. Chúa hứa việc bà làm sẽ được nhắc khắp nơi có Tin Mừng.", "People criticize using costly ointment as waste. The Lord says leave her alone; she has done a beautiful thing for me; the poor are always with you but I am not. She anointed beforehand for burial. He promises her deed will be told wherever the Gospel is preached.", "Tình yêu dành cho Chúa không phải phí phạm. Dành thời gian Thánh Thể, kinh nguyện, và nhớ bác ái với người nghèo.", "Love for the Lord is no waste. Give time to the Eucharist and prayer, and remember charity to the poor."]);
WORDS.push(["Mark", 14, 13, 15, "Phòng lớn đã sắp sẵn", "A large room furnished and ready", "Chúa sai hai môn đệ vào thành gặp người mang vò nước, theo ông và nói với chủ nhà: “Thầy bảo: phòng của Thầy ở đâu để Thầy ăn lễ Vượt Qua?” Ông sẽ chỉ cho một căn phòng lớn đã sắp đặt sẵn. Chúa chuẩn bị mọi sự: Chúa làm chủ chương trình Thương Khó.", "The Lord sends two disciples into the city to meet a man carrying a jar of water, follow him and ask the householder: “Where is my guest room for the Passover?” He will show a large upper room furnished and ready. The Lord prepares all: he is master of the Passion’s plan.", "Chúa chuẩn bị chỗ cho ta. Hãy chuẩn bị “căn phòng” của tâm hồn để rước Chúa trong Thánh Thể.", "The Lord prepares a place for us. Prepare the “room” of your heart to receive him in the Eucharist."]);
WORDS.push(["Mark", 14, 18, 21, "Một người trong các con sẽ nộp Thầy", "One of you will betray me", "Trong bữa ăn Chúa nói: “Một người đang ăn với Thầy sẽ nộp Thầy.” Họ buồn và hỏi từng người “Có phải con không?” Chúa nói người nộp Con Người thật khốn, thà nó đừng sinh ra. Sự phản bội của người thân thiết là đau nhất; Chúa vẫn tôn trọng tự do của họ.", "During the meal the Lord says: “One of you eating with me will betray me.” They are grieved and ask each “Is it I?” He says woe to the betrayer; better he had not been born. Betrayal by a close friend hurts most; the Lord still respects their freedom.", "Hãy tự hỏi “có phải con không?” khi nghĩ đến mình đã bỏ Chúa bằng tội lỗi. Đến xin tha thứ.", "Ask “is it I?” when thinking of how I have abandoned the Lord by sin. Come to seek pardon."]);
WORDS.push(["Mark", 14, 22, 25, "Thiết lập Thánh Thể", "The institution of the Eucharist", "“Các con cầm lấy, đây là Mình Thầy.” “Đây là Máu Thầy, Máu Giao Ước, đổ ra cho nhiều người.” Chúa xưng tụng, bẻ bánh, trao chén: Hy lễ thập giá được hiện diện trong bữa tiệc trước. Người nói sẽ không uống rượu nữa cho đến ngày uống rượu mới trong Nước Thiên Chúa. Thánh Thể là lời hứa bữa tiệc vĩnh cửu.", "“Take; this is my body.” “This is my blood of the covenant, poured out for many.” The Lord blesses, breaks the bread, gives the cup: the cross’s sacrifice is made present in the prior supper. He says he will drink no more until the day he drinks it new in the Kingdom of God. The Eucharist is promise of the eternal banquet.", "Hãy tham dự Thánh Lễ với đức tin: ở đó Chúa trao chính Người. Khi rước lễ, hãy thưa “Amen” với cả lòng.", "Participate in Mass with faith: there the Lord gives himself. When receiving say “Amen” with your whole heart."]);
WORDS.push(["Mark", 14, 27, 31, "Ai cũng sẽ vấp ngã; Phêrô sẽ chối", "All will fall away; Peter will deny", "Chúa nói tất cả sẽ vấp ngã vì “Ta sẽ đánh người chăn và đàn chiên sẽ tan tác”, nhưng sau khi sống lại Người sẽ đi trước đến Galilê. Phêrô tuyên bố dù mọi người ngã ông cũng không. Chúa báo ông sẽ chối ba lần trước khi gà gáy lần hai. Phêrô càng quả quyết. Chúa thấy yếu đuối nhưng không bỏ.", "The Lord says all will fall away for “I will strike the shepherd and the sheep will be scattered,” but after rising he will go before them to Galilee. Peter declares though all fall he will not. The Lord says he will deny him three times before the cock crows twice. Peter insists more. The Lord sees weakness yet does not abandon.", "Biết mình yếu để khiêm tốn xin ơn. Sau mỗi lần vấp ngã, hãy trở về “Galilê” là nơi Chúa đã hẹn gặp lại.", "Knowing your weakness be humble and ask grace. After each fall return to “Galilee,” where the Lord waits."]);
WORDS.push(["Mark", 14, 32, 42, "Cầu nguyện ở Ghếtsêmani: Abba, Cha", "Prayer at Gethsemane: Abba, Father", "Chúa nói “Tâm hồn Thầy buồn đến chết được; các con ở đây và tỉnh thức.” Người sấp mình cầu nguyện “Abba, Cha ơi, mọi sự đều có thể đối với Cha; xin cất chén này khỏi con; nhưng xin đừng theo ý con, mà theo ý Cha.” Ba lần trở lại thấy họ ngủ, Người nói “Thức và cầu nguyện kẻo sa chước cám dỗ”. “Abba” là tiếng gọi thân mật của đứa con với cha.", "The Lord says “My soul is very sorrowful, even to death; remain here and watch.” He falls on the ground praying: “Abba, Father, all things are possible to you; remove this cup from me; yet not what I will but what you will.” Three times returning to find them asleep he says “Watch and pray that you may not enter into temptation.” “Abba” is the child’s intimate call to a father.", "Hãy gọi Thiên Chúa là “Abba” trong cầu nguyện, kể cả nỗi sợ. Rồi thưa “xin ý Cha được thể hiện”.", "Call God “Abba” in prayer, even in fear. Then say “your will be done.”"]);
WORDS.push(["Mark", 14, 48, 49, "Như đi bắt cướp sao?", "Have you come out as against a robber?", "Khi bị bắt, Chúa hỏi: các ông đem gươm gậy đến bắt Tôi như bắt cướp sao? Ngày nào Tôi cũng ở trong Đền Thờ giảng dạy mà các ông không bắt. Nhưng “để ứng nghiệm Kinh Thánh”. Chúa biết đây là giờ của bóng tối nhưng cũng là chương trình của Cha.", "When arrested the Lord asks: have you come out with swords and clubs to seize me as a robber? Daily I was in the Temple teaching and you did not arrest me. But “let the Scriptures be fulfilled.” He knows this is the hour of darkness yet also the Father’s plan.", "Khi bị bắt bớ bất công, hãy nhớ Chúa đã chịu và vẫn bình an. Hãy tin vào chương trình của Cha.", "When unjustly arrested or treated remember the Lord endured and stayed peaceful. Trust the Father’s plan."]);
WORDS.push(["Mark", 14, 62, 62, "Ta là Đấng ấy", "I am", "Thượng tế hỏi Người có phải là Đấng Kitô, Con Đấng Đáng Chúc Tụng. Chúa đáp rõ ràng: “Ta là” (Ego eimi, cách Thiên Chúa xưng danh), và nói họ sẽ thấy Con Người ngự bên hữu Đấng Quyền Năng và đến trên mây trời. Tuyên bố công khai này dẫn tới án tử hình.", "The high priest asks if he is the Christ, the Son of the Blessed. The Lord answers clearly: “I am” (the way God names himself), and says they will see the Son of Man seated at the right hand of Power and coming with the clouds. This open declaration leads to the death sentence.", "Hãy tuyên xưng Chúa Giêsu là Đấng Cứu Thế bằng cả đời sống. Người đã chịu chết vì sự thật ấy.", "Profess Jesus as Saviour with your whole life. He died for this truth."]);
WORDS.push(["Mark", 15, 2, 2, "Chính ngài nói đó", "You have said so", "Philatô hỏi Chúa có phải vua dân Do Thái. Chúa đáp: “Chính ông nói đó.” Đây là lời duy nhất Người nói trước tòa án Rôma, rồi im lặng trước mọi tố cáo. Người thật là Vua, nhưng vương quyền của Người là vâng phục, hy sinh. Philatô ngạc nhiên.", "Pilate asks whether he is the King of the Jews. The Lord answers: “You say so.” This is his only word before the Roman court; then silence before accusations. He truly is King, but his kingship is obedience and sacrifice. Pilate is astonished.", "Có lúc im lặng cầu nguyện là câu trả lời đúng nhất. Hãy học từ sự im lặng của Chúa.", "Sometimes prayerful silence is the best answer. Learn from the Lord’s silence."]);
WORDS.push(["Mark", 15, 34, 34, "Eloi, Eloi, lama sabacthani", "Eloi, Eloi, lama sabachthani", "Giờ thứ chín, Chúa kêu lớn tiếng bằng tiếng Aram: “Lạy Thiên Chúa, Thiên Chúa của con, sao Ngài bỏ rơi con?” Đây là lời mở đầu Thánh vịnh 22 và lời cuối cùng Máccô ghi trong Cuộc Thương Khó. Người chịu sự cô đơn tận cùng để không ai còn phải chịu cô đơn tuyệt đối. Sau đó Người trút hơi thở.", "At the ninth hour the Lord cries aloud in Aramaic: “My God, my God, why have you forsaken me?” This is the opening of Psalm 22 and the last word Mark records in the Passion. He bears utter loneliness so none need bear absolute loneliness. Then he breathes his last.", "Khi cảm thấy Chúa xa vắng, hãy dùng lời Thánh vịnh 22 để cầu nguyện. Người đã đi qua con đường ấy trước ta.", "When God feels absent pray with Psalm 22. He passed this way before us."]);
WORDS.push(["Mark", 16, 15, 18, "Hãy đi loan báo Tin Mừng cho mọi loài thọ tạo", "Go into all the world and proclaim the Gospel", "Chúa Phục Sinh hiện ra với Mười Một và trách họ cứng lòng, rồi sai đi: hãy rao giảng Tin Mừng cho mọi loài thọ tạo. Ai tin và chịu phép rửa sẽ được cứu; ai không tin sẽ bị lên án. Những dấu lạ sẽ đi kèm người tin: trừ quỷ, nói tiếng mới, chữa lành. Sứ mạng truyền giáo là nhiệm vụ của mọi Kitô hữu.", "The Risen Lord appears to the Eleven, rebukes their hardness, then sends them: proclaim the Gospel to the whole creation. Whoever believes and is baptized will be saved; whoever does not believe will be condemned. Signs will accompany believers: casting out demons, new tongues, healing. Mission is the task of every Christian.", "Đức tin phải được chia sẻ. Hãy kể cho một người về niềm vui đức tin của bạn bằng đời sống và lời nói, trong tuần này.", "Faith must be shared. This week tell one person of the joy of your faith by life and word."]);
